writeNewRepair("app/dashboard/(portal)/settings/NotificationsCard.tsx", "limited: \"email limit reached\",", false,
    "\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\n\ntype Severity = \"normal\" | \"high\";\n\ninterface NotifySettings {\n  email_enabled: boolean;\n  email_to: string;\n  min_severity: Severity;\n  kinds: Record<string, boolean>;\n  bell_per_hour: number;\n  email_per_hour: number;\n  email_per_day: number;\n}\n\ntype LimitKey = \"bell_per_hour\" | \"email_per_hour\" | \"email_per_day\";\n\nconst LIMITS: { key: LimitKey; label: string }[] = [\n  { key: \"bell_per_hour\", label: \"Bell alerts per kind, per hour\" },\n  { key: \"email_per_hour\", label: \"Emails per kind, per hour\" },\n  { key: \"email_per_day\", label: \"Emails per day (all kinds)\" },\n];\n\ninterface NotifyKind {\n  key: string;\n  label: string;\n  description: string;\n}\n\ninterface NotificationItem {\n  id: number;\n  kind: string;\n  severity: Severity;\n  title: string;\n  detail: string;\n  conversation_id: number | null;\n  email_to: string;\n  email_status: string;\n  email_error: string;\n  created_at: string | null;\n  in_app_status: string;\n}\n\ninterface Payload {\n  items: NotificationItem[];\n  settings: NotifySettings;\n  kinds: NotifyKind[];\n  severities: Severity[];\n  email_configured: boolean;\n  limit_max: number;\n  can_edit: boolean;\n}\n\ninterface TestResult {\n  ok: boolean;\n  result: {\n    in_app: number | null;\n    email: string;\n    email_to: string;\n    ledger_id: number | null;\n    error: string;\n  };\n}\n\nconst inputClass =\n  \"w-full rounded-xl border border-line bg-soft px-3.5 py-2.5 text-sm text-ink placeholder:text-ink-3 outline-none transition-colors duration-300 focus:border-brand/40\";\nconst primaryBtn =\n  \"rounded-xl border border-brand/25 bg-brand-soft px-4 py-2 text-xs font-medium text-brand transition-colors duration-300 hover:bg-brand-soft disabled:opacity-50\";\nconst ghostBtn =\n  \"rounded-xl border border-line px-3 py-2 text-xs text-ink-3 transition-colors duration-300 hover:text-ink disabled:opacity-50\";\n\nconst EMAIL_STATUS_LABEL: Record<string, string> = {\n  off: \"bell only\",\n  sent: \"email sent\",\n  queued: \"email queued\",\n  failed: \"email failed\",\n  deduped: \"already open\",\n  no_recipient: \"no recipient\",\n  limited: \"email limit reached\",\n};\n\nfunction formatWhen(iso: string | null): string {\n  if (!iso) return \"\";\n  const then = new Date(iso).getTime();\n  if (Number.isNaN(then)) return \"\";\n  const minutes = Math.max(0, Math.floor((Date.now() - then) / 60000));\n  if (minutes < 1) return \"just now\";\n  if (minutes < 60) return minutes + \"m ago\";\n  const hours = Math.floor(minutes / 60);\n  if (hours < 24) return hours + \"h ago\";\n  return Math.floor(hours / 24) + \"d ago\";\n}\n\n/**\n * Settings -> Notifications: what reaches the owner outside the dashboard.\n * The bell is always on (its own switch lives in the bell); email is an\n * opt-in per workspace with a recipient, a severity threshold and per-kind\n * toggles rendered from the Control Plane registry. \"Send a test\" runs the\n * real fan-out and shows the honest result.\n */\nexport default function NotificationsCard() {\n  const [data, setData] = useState<Payload | null>(null);\n  const [form, setForm] = useState<NotifySettings | null>(null);\n  const [loaded, setLoaded] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const [notice, setNotice] = useState<{ kind: \"ok\" | \"error\"; text: string } | null>(null);\n  const [showHistory, setShowHistory] = useState(false);\n\n  const load = useCallback(async () => {\n    try {\n      const response = await fetch(\"/api/omniflow/portal/notifications?limit=20\", {\n        credentials: \"same-origin\",\n        cache: \"no-store\",\n      });\n      if (!response.ok) {\n        setData(null);\n        return;\n      }\n      const body = (await response.json()) as Payload;\n      setData(body);\n      setForm(body.settings);\n    } catch {\n      setData(null);\n    } finally {\n      setLoaded(true);\n    }\n  }, []);\n\n  useEffect(() => {\n    void load();\n  }, [load]);\n\n  async function save() {\n    if (!form) return;\n    setBusy(true);\n    setNotice(null);\n    // limits are owner / admin settings - other roles send the rest only\n    const { bell_per_hour, email_per_hour, email_per_day, ...basic } = form;\n    const payload = data?.can_edit ? { ...basic, bell_per_hour, email_per_hour, email_per_day } : basic;\n    try {\n      const response = await fetch(\"/api/omniflow/portal/notifications/settings\", {\n        method: \"PUT\",\n        credentials: \"same-origin\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(payload),\n      });\n      const body = (await response.json().catch(() => null)) as\n        | { settings?: NotifySettings; error?: { message?: string } }\n        | null;\n      if (!response.ok) {\n        setNotice({\n          kind: \"error\",\n          text: body?.error?.message ?? \"Those settings could not be saved.\",\n        });\n        return;\n      }\n      if (body?.settings) setForm(body.settings);\n      setNotice({ kind: \"ok\", text: \"Notification settings saved.\" });\n      await load();\n    } catch {\n      setNotice({ kind: \"error\", text: \"Could not reach the workspace. Try again shortly.\" });\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function sendTest() {\n    setBusy(true);\n    setNotice(null);\n    try {\n      const response = await fetch(\"/api/omniflow/portal/notifications/test\", {\n        method: \"POST\",\n        credentials: \"same-origin\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: \"{}\",\n      });\n      const body = (await response.json().catch(() => null)) as TestResult | null;\n      if (!response.ok || !body) {\n        setNotice({ kind: \"error\", text: \"The test could not be sent. Try again shortly.\" });\n        return;\n      }\n      const r = body.result;\n      const bell = r.in_app ? \"Bell alert created\" : \"Bell alert skipped (alerts are off or one is already open)\";\n      const email =\n        r.email === \"sent\"\n          ? \"email sent to \" + r.email_to\n          : r.email === \"failed\"\n            ? \"email failed: \" + (r.error || \"delivery error\")\n            : r.email === \"no_recipient\"\n              ? \"email skipped: no recipient\"\n              : r.email === \"off\"\n                ? \"email is off\"\n                : \"email \" + r.email;\n      setNotice({ kind: r.email === \"failed\" ? \"error\" : \"ok\", text: bell + \" \\u00b7 \" + email + \".\" });\n      await load();\n    } catch {\n      setNotice({ kind: \"error\", text: \"Could not reach the workspace. Try again shortly.\" });\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  const kinds = data?.kinds ?? [];\n\n  return (\n    <section className=\"rounded-2xl border border-line bg-white shadow-card p-5\">\n      <div className=\"flex flex-wrap items-start justify-between gap-3\">\n        <div>\n          <h2 className=\"text-sm font-semibold text-ink\">Notifications</h2>\n          <p className=\"mt-1 text-xs text-ink-3\">\n            Handoffs, approvals, failed deliveries and workflow problems always\n            reach the bell. Turn on email to be told when you are away from the\n            dashboard.\n          </p>\n        </div>\n        {data && !data.email_configured ? (\n          <span className=\"rounded-full border border-amber-400/30 bg-amber-400/[0.08] px-2 py-0.5 text-[10px] text-amber-700\">\n            Email provider not configured on the platform\n          </span>\n        ) : null}\n      </div>\n\n      {!loaded ? (\n        <p className=\"mt-3 text-xs text-ink-3\">Loading&#8230;</p>\n      ) : !data || !form ? (\n        <p className=\"mt-3 text-xs text-ink-3\">\n          Notification settings are unavailable right now. Try again shortly.\n        </p>\n      ) : (\n        <>\n          <div className=\"mt-4 space-y-3\">\n            <label className=\"flex items-center gap-2 text-xs text-ink\">\n              <input\n                type=\"checkbox\"\n                checked={form.email_enabled}\n                onChange={(event) => setForm({ ...form, email_enabled: event.target.checked })}\n                className=\"h-4 w-4 rounded border-line\"\n              />\n              Email me as well as the bell\n            </label>\n            <div className=\"grid gap-2 sm:grid-cols-2\">\n              <div>\n                <p className=\"mb-1 text-[11px] text-ink-3\">Send to</p>\n                <input\n                  value={form.email_to}\n                  onChange={(event) => setForm({ ...form, email_to: event.target.value })}\n                  placeholder=\"Leave blank to use the workspace owner's address\"\n                  maxLength={200}\n                  className={inputClass}\n                />\n              </div>\n              <div>\n                <p className=\"mb-1 text-[11px] text-ink-3\">Email me for</p>\n                <select\n                  value={form.min_severity}\n                  onChange={(event) =>\n                    setForm({ ...form, min_severity: event.target.value === \"high\" ? \"high\" : \"normal\" })\n                  }\n                  className={inputClass}\n                >\n                  <option value=\"normal\">Everything I have switched on</option>\n                  <option value=\"high\">Only high-priority (policy blocks, approvals, revenue)</option>\n                </select>\n              </div>\n            </div>\n            <div>\n              <p className=\"mb-1 text-[11px] text-ink-3\">What to email about</p>\n              <ul className=\"grid gap-1.5 sm:grid-cols-2\">\n                {kinds.map((kind) => (\n                  <li key={kind.key}>\n                    <label className=\"flex items-start gap-2 rounded-xl border border-line px-3 py-2 text-xs text-ink\">\n                      <input\n                        type=\"checkbox\"\n                        checked={form.kinds[kind.key] !== false}\n                        onChange={(event) =>\n                          setForm({\n                            ...form,\n                            kinds: { ...form.kinds, [kind.key]: event.target.checked },\n                          })\n                        }\n                        className=\"mt-0.5 h-4 w-4 rounded border-line\"\n                      />\n                      <span>\n                        <span className=\"font-medium\">{kind.label}</span>\n                        <span className=\"block text-[10px] text-ink-3\">{kind.description}</span>\n                      </span>\n                    </label>\n                  </li>\n                ))}\n              </ul>\n            </div>\n            <div>\n              <p className=\"mb-1 text-[11px] text-ink-3\">Limits</p>\n              <div className=\"grid gap-2 sm:grid-cols-3\">\n                {LIMITS.map((limit) => (\n                  <label key={limit.key} className=\"text-[11px] text-ink-3\">\n                    {limit.label}\n                    <input\n                      type=\"number\"\n                      min={1}\n                      max={data.limit_max}\n                      value={form[limit.key]}\n                      disabled={!data.can_edit || busy}\n                      onChange={(event) =>\n                        setForm({ ...form, [limit.key]: Math.trunc(Number(event.target.value) || 0) })\n                      }\n                      className={inputClass + \" mt-1\"}\n                    />\n                  </label>\n                ))}\n              </div>\n              <p className=\"mt-1 text-[10px] text-ink-3\">\n                High-priority notifications skip the hourly limits. Anything held back stays in Recent\n                notifications, and the next email says how many were held.\n                {data.can_edit ? \"\" : \" Only owners and admins can change limits.\"}\n              </p>\n            </div>\n          </div>\n\n          <div className=\"mt-4 flex flex-wrap items-center gap-2\">\n            <button type=\"button\" onClick={() => void save()} disabled={busy} className={primaryBtn}>\n              {busy ? \"Working\\u2026\" : \"Save\"}\n            </button>\n            <button type=\"button\" onClick={() => void sendTest()} disabled={busy} className={ghostBtn}>\n              Send a test\n            </button>\n            <button\n              type=\"button\"\n              onClick={() => setShowHistory((value) => !value)}\n              className={ghostBtn}\n            >\n              {showHistory ? \"Hide recent\" : \"Recent notifications\"}\n            </button>\n          </div>\n          {notice ? (\n            <p className={\"mt-3 text-xs \" + (notice.kind === \"ok\" ? \"text-ok\" : \"text-danger\")}>\n              {notice.text}\n            </p>\n          ) : null}\n\n          {showHistory ? (\n            data.items.length === 0 ? (\n              <p className=\"mt-3 text-xs text-ink-3\">Nothing has been sent yet.</p>\n            ) : (\n              <ul className=\"mt-3 space-y-1.5\">\n                {data.items.map((item) => (\n                  <li key={item.id} className=\"rounded-xl border border-line px-3 py-2\">\n                    <div className=\"flex items-center justify-between gap-2\">\n                      <p className=\"min-w-0 truncate text-xs text-ink\">\n                        {item.severity === \"high\" ? (\n                          <span className=\"mr-1 text-amber-600\">&#9679;</span>\n                        ) : null}\n                        {item.title}\n                      </p>\n                      <span className=\"shrink-0 text-[10px] text-ink-3\">\n                        {formatWhen(item.created_at)}\n                      </span>\n                    </div>\n                    <p className=\"mt-0.5 text-[10px] text-ink-3\">\n                      {item.kind}\n                      {item.in_app_status === \"limited\" ? \" \\u00b7 bell limit reached\" : \"\"}\n                      {\" \\u00b7 \"}\n                      {EMAIL_STATUS_LABEL[item.email_status] ?? item.email_status}\n                      {item.email_to ? \" (\" + item.email_to + \")\" : \"\"}\n                      {item.email_error ? \" \\u2014 \" + item.email_error : \"\"}\n                      {item.conversation_id ? (\n                        <>\n                          {\" \\u00b7 \"}\n                          <a\n                            href={\"/dashboard/conversations/\" + item.conversation_id}\n                            className=\"text-brand hover:underline\"\n                          >\n                            open chat\n                          </a>\n                        </>\n                      ) : null}\n                    </p>\n                  </li>\n                ))}\n              </ul>\n            )\n          ) : null}\n        </>\n      )}\n    </section>\n  );\n}\n");
writeNewRepair("app/dashboard/(portal)/settings/NotificationTemplatesCard.tsx", " * \u00a7239 Settings -> Email templates", false,
    "\"use client\";\n\nimport { useEffect, useState } from \"react\";\n\nimport type { NotifyTemplate, NotifyTemplatesView } from \"../../../../lib/omniflow/portal\";\n\nconst BASE = \"/api/omniflow/portal/notifications/templates\";\n\nconst inputClass =\n  \"w-full rounded-xl border border-line bg-soft px-3.5 py-2.5 text-sm text-ink placeholder:text-ink-3 outline-none transition-colors duration-300 focus:border-brand/40\";\nconst primaryBtn =\n  \"rounded-xl border border-brand/25 bg-brand-soft px-4 py-2 text-xs font-medium text-brand transition-colors duration-300 hover:bg-brand-soft disabled:opacity-50\";\nconst ghostBtn =\n  \"rounded-xl border border-line px-3 py-2 text-xs text-ink-3 transition-colors duration-300 hover:text-ink disabled:opacity-50\";\n\nasync function call<T>(url: string, method: string, body?: unknown): Promise<{ ok: boolean; data: T | null; message: string }> {\n  try {\n    const response = await fetch(url, {\n      method,\n      credentials: \"same-origin\",\n      cache: \"no-store\",\n      headers: body === undefined ? undefined : { \"Content-Type\": \"application/json\" },\n      body: body === undefined ? undefined : JSON.stringify(body),\n    });\n    const data = (await response.json().catch(() => null)) as (T & { error?: { message?: string } }) | null;\n    return {\n      ok: response.ok,\n      data: response.ok ? data : null,\n      message: data?.error?.message ?? \"That did not work. Try again shortly.\",\n    };\n  } catch {\n    return { ok: false, data: null, message: \"Could not reach the workspace. Try again shortly.\" };\n  }\n}\n\n/**\n * \u00a7239 Settings -> Email templates: one subject + body per notification\n * kind, with variables. Blank = the built-in email. Preview renders sample\n * values on the Control Plane; \"Send a test\" sends this kind for real.\n */\nexport default function NotificationTemplatesCard() {\n  const [view, setView] = useState<NotifyTemplatesView | null>(null);\n  const [failed, setFailed] = useState(false);\n  const [kind, setKind] = useState(\"escalation\");\n  const [subject, setSubject] = useState(\"\");\n  const [body, setBody] = useState(\"\");\n  const [preview, setPreview] = useState<{ subject: string; body: string } | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [notice, setNotice] = useState<{ ok: boolean; text: string } | null>(null);\n\n  function pick(next: NotifyTemplatesView, key: string) {\n    const item = next.templates.find((t) => t.kind === key) ?? next.templates[0];\n    if (!item) return;\n    setKind(item.kind);\n    setSubject(item.subject);\n    setBody(item.body);\n    setPreview(null);\n  }\n\n  useEffect(() => {\n    void (async () => {\n      const result = await call<NotifyTemplatesView>(BASE, \"GET\");\n      if (!result.data) {\n        setFailed(true);\n        return;\n      }\n      setView(result.data);\n      pick(result.data, \"escalation\");\n    })();\n  }, []);\n\n  async function run(action: \"preview\" | \"save\" | \"reset\" | \"test\") {\n    if (!view) return;\n    setBusy(true);\n    setNotice(null);\n    if (action === \"preview\") {\n      const result = await call<{ subject: string; body: string }>(BASE + \"/preview\", \"POST\", {\n        kind,\n        subject: subject || view.defaults.subject,\n        body: body || view.defaults.body,\n      });\n      if (result.data) setPreview(result.data);\n      else setNotice({ ok: false, text: result.message });\n    } else if (action === \"test\") {\n      const result = await call<{ result: { email: string; error: string } }>(\n        \"/api/omniflow/portal/notifications/test\",\n        \"POST\",\n        { kind }\n      );\n      const email = result.data?.result.email ?? \"\";\n      setNotice(\n        result.data\n          ? {\n              ok: email !== \"failed\",\n              text:\n                email === \"sent\"\n                  ? \"Test email sent with this template.\"\n                  : email === \"failed\"\n                    ? \"Test email failed: \" + (result.data.result.error || \"delivery error\")\n                    : \"Bell alert sent; email is \" + (email || \"off\") + \" for this kind.\",\n            }\n          : { ok: false, text: result.message }\n      );\n    } else {\n      const result =\n        action === \"save\"\n          ? await call<NotifyTemplatesView>(BASE + \"/\" + kind, \"PUT\", { subject, body })\n          : await call<NotifyTemplatesView>(BASE + \"/\" + kind, \"DELETE\");\n      if (result.data) {\n        setView(result.data);\n        pick(result.data, kind);\n        setNotice({ ok: true, text: action === \"save\" ? \"Template saved.\" : \"Back to the built-in email.\" });\n      } else {\n        setNotice({ ok: false, text: result.message });\n      }\n    }\n    setBusy(false);\n  }\n\n  const current: NotifyTemplate | undefined = view?.templates.find((t) => t.kind === kind);\n  const locked = !view?.canEdit || busy;\n\n  return (\n    <section className=\"rounded-2xl border border-line bg-white shadow-card p-5\">\n      <h2 className=\"text-sm font-semibold text-ink\">Email templates</h2>\n      <p className=\"mt-1 text-xs text-ink-3\">\n        Change the subject and wording of notification emails per kind. Leave a kind blank to use the built-in email.\n      </p>\n      {failed ? (\n        <p className=\"mt-3 text-xs text-ink-3\">Email templates are unavailable right now. Try again shortly.</p>\n      ) : !view ? (\n        <p className=\"mt-3 text-xs text-ink-3\">Loading&#8230;</p>\n      ) : (\n        <>\n          <div className=\"mt-4 grid gap-3\">\n            <select\n              value={kind}\n              onChange={(event) => pick(view, event.target.value)}\n              className={inputClass}\n              aria-label=\"Notification kind\"\n            >\n              {view.templates.map((item) => (\n                <option key={item.kind} value={item.kind}>\n                  {item.label + (item.custom ? \" (custom)\" : \"\")}\n                </option>\n              ))}\n            </select>\n            <input\n              value={subject}\n              onChange={(event) => setSubject(event.target.value)}\n              placeholder={view.defaults.subject}\n              maxLength={view.subjectMax}\n              disabled={locked}\n              className={inputClass}\n              aria-label=\"Subject\"\n            />\n            <textarea\n              value={body}\n              onChange={(event) => setBody(event.target.value)}\n              placeholder={view.defaults.body}\n              maxLength={view.bodyMax}\n              rows={6}\n              disabled={locked}\n              className={inputClass + \" font-mono text-xs\"}\n              aria-label=\"Body\"\n            />\n            <ul className=\"flex flex-wrap gap-1.5\">\n              {view.variables.map((variable) => (\n                <li\n                  key={variable.key}\n                  title={variable.description}\n                  className=\"rounded-full border border-line px-2 py-0.5 font-mono text-[10px] text-ink-2\"\n                >\n                  {\"{\" + variable.key + \"}\"}\n                </li>\n              ))}\n            </ul>\n          </div>\n          <div className=\"mt-4 flex flex-wrap items-center gap-2\">\n            {!subject && !body ? (\n              <button\n                type=\"button\"\n                onClick={() => {\n                  setSubject(view.defaults.subject);\n                  setBody(view.defaults.body);\n                }}\n                disabled={locked}\n                className={ghostBtn}\n              >\n                Start from the built-in email\n              </button>\n            ) : null}\n            <button type=\"button\" onClick={() => void run(\"preview\")} disabled={busy} className={ghostBtn}>\n              Preview\n            </button>\n            <button type=\"button\" onClick={() => void run(\"save\")} disabled={locked} className={primaryBtn}>\n              {busy ? \"Working\\u2026\" : \"Save\"}\n            </button>\n            {current?.custom ? (\n              <button type=\"button\" onClick={() => void run(\"reset\")} disabled={locked} className={ghostBtn}>\n                Reset to built-in\n              </button>\n            ) : null}\n            <button type=\"button\" onClick={() => void run(\"test\")} disabled={busy} className={ghostBtn}>\n              Send a test\n            </button>\n          </div>\n          {!view.canEdit ? (\n            <p className=\"mt-2 text-[11px] text-ink-3\">Only owners and admins can change email templates.</p>\n          ) : null}\n          {notice ? (\n            <p className={\"mt-3 text-xs \" + (notice.ok ? \"text-ok\" : \"text-danger\")}>{notice.text}</p>\n          ) : null}\n          {preview ? (\n            <div className=\"mt-3 rounded-xl border border-line bg-soft p-3\">\n              <p className=\"text-xs font-medium text-ink\">{preview.subject}</p>\n              <p className=\"mt-2 whitespace-pre-wrap text-xs text-ink-2\">{preview.body}</p>\n              <p className=\"mt-2 text-[10px] text-ink-3\">Sample values - nothing was sent.</p>\n            </div>\n          ) : null}\n        </>\n      )}\n    </section>\n  );\n}\n");
